draw:
var v = 343;
var vs = p.speed;
var f0 = p.freq;
var loop = 3.0;
var Te = 0.3;
var tau = t % loop;
var Wm = Math.max(v, vs) * loop * 1.08;
var x0 = 16;
var sc = (W - 32) / Wm;
var y0 = H * 0.55;

ctx.font = '12px ui-sans-serif, system-ui, sans-serif';
ctx.lineWidth = 1;

// road line
ctx.strokeStyle = C.faint;
ctx.beginPath();
ctx.moveTo(0, y0 + 46);
ctx.lineTo(W, y0 + 46);
ctx.stroke();

// wavefronts
ctx.strokeStyle = C.rule;
for (var k = 0; k * Te <= tau; k++) {
  var te = k * Te;
  var r = v * (tau - te) * sc;
  var cx = x0 + vs * te * sc;
  if (r < 0.5) continue;
  ctx.beginPath();
  ctx.arc(cx, y0, r, 0, Math.PI * 2);
  ctx.stroke();
}

var sxNow = x0 + vs * tau * sc;

// Mach cone
if (vs > v) {
  var th = Math.asin(v / vs);
  var L = W;
  ctx.strokeStyle = C.accent;
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.moveTo(sxNow, y0);
  ctx.lineTo(sxNow - L * Math.cos(th), y0 - L * Math.sin(th));
  ctx.moveTo(sxNow, y0);
  ctx.lineTo(sxNow - L * Math.cos(th), y0 + L * Math.sin(th));
  ctx.stroke();
  ctx.lineWidth = 1;
  ctx.fillStyle = C.accent;
  ctx.fillText('shock cone', 14, 18);
}

// source
ctx.fillStyle = C.accent;
ctx.beginPath();
ctx.arc(sxNow, y0, 5, 0, Math.PI * 2);
ctx.fill();
ctx.fillStyle = C.ink;
ctx.fillText('source', sxNow - 18, y0 - 10);

// listeners
ctx.fillStyle = C.figure;
ctx.beginPath();
ctx.arc(W - 12, y0, 4, 0, Math.PI * 2);
ctx.fill();
ctx.beginPath();
ctx.arc(10, y0, 4, 0, Math.PI * 2);
ctx.fill();
ctx.fillStyle = C.ink;
ctx.fillText('ahead', W - 52, y0 + 22);
ctx.fillText('behind', 6, y0 + 22);

if (vs < v) {
  var fA = f0 * v / (v - vs);
  var fB = f0 * v / (v + vs);
  out.note = 'ahead ' + fA.toFixed(1) + ' Hz, behind ' + fB.toFixed(1) + ' Hz, true ' + f0.toFixed(0) + ' Hz';
} else if (vs === v) {
  out.note = 'Mach 1.00: every crest arrives at once, the fronts touch at the source';
} else {
  var thh = Math.asin(v / vs) * 180 / Math.PI;
  out.note = 'Mach ' + (vs / v).toFixed(2) + ', cone half-angle ' + thh.toFixed(1) + ' degrees, no sound ahead';
}
